(487517, 47264, 9168, '<td valign="top">I thought of a similar idea.  I was going to call it Under the Weather.</td>', 'I thought of a similar idea.  I was going to call it Under the Weather.', '2003-11-17 01:12:58.000000', NULL, 1),
(487519, 47211, 13576, '<td valign="top">Good photo.. wrong title. Cutting the Cheese is the first thing that came to mind.<br/>Bit of a glare on the front of the blade. Focus could have been a bit better on the cheese. Good imagination.</td>', 'Good photo.. wrong title. Cutting the Cheese is the first thing that came to mind.Bit of a glare on the front of the blade. Focus could have been a bit better on the cheese. Good imagination.', '2003-11-17 01:13:49.000000', NULL, 1),
(487520, 47221, 12661, '<td valign="top">Wow. You killed two birds with one stone in this challenge. ;) I love the contrast of the different fruits and the black background worked very well with this. Get rid of those few hot pixels on the bottom right and this photo will be ready for a print.</td>', 'Wow. You killed two birds with one stone in this challenge. ;) I love the contrast of the different fruits and the black background worked very well with this. Get rid of those few hot pixels on the bottom right and this photo will be ready for a print.', '2003-11-17 01:14:14.000000', NULL, 1),
(487521, 47211, 9168, '<td valign="top">...or "Cut the Cheese" :)</td>', '...or "Cut the Cheese" :)', '2003-11-17 01:16:20.000000', NULL, 1),
(487523, 47356, 12661, '<td valign="top">Needs ketchup.</td>', 'Needs ketchup.', '2003-11-17 01:17:37.000000', NULL, 1),
