(487534, 47263, 10170, '<td valign="top">Perfect for the challenge and very nicely taken shot.  The lighting is excellent.</td>', 'Perfect for the challenge and very nicely taken shot.  The lighting is excellent.', '2003-11-17 01:36:27.000000', NULL, 1),
