(488232, 47022, 3102, '<td valign="top">Clever!  Must have been fun to clean up that mess!</td>', 'Clever!  Must have been fun to clean up that mess!', '2003-11-17 15:54:00.000000', NULL, 1),
(488234, 47358, 3102, '<td valign="top">Not sure about the funky shadows, but the idea is very well carried out!</td>', 'Not sure about the funky shadows, but the idea is very well carried out!', '2003-11-17 15:54:25.000000', NULL, 1),
(488244, 47100, 7889, '<td valign="top">Colour is good but lighting is too harsh.</td>', 'Colour is good but lighting is too harsh.', '2003-11-17 16:19:55.000000', NULL, 1),
(488245, 47122, 6667, '<td valign="top">Money needs to be a little sharper in focus.</td>', 'Money needs to be a little sharper in focus.', '2003-11-17 16:23:07.000000', NULL, 1),
(488248, 47063, 6667, '<td valign="top">Two questions:  Did these worms get a bath before they were canned?  Is this a Spam can?  Please tell me it isn''t .  I love Spam ( at least I did).  Nice shot. Great interpretation.</td>', 'Two questions:  Did these worms get a bath before they were canned?  Is this a Spam can?  Please tell me it isn''t .  I love Spam ( at least I did).  Nice shot. Great interpretation.', '2003-11-17 16:26:16.000000', NULL, 1),
(488250, 46914, 7889, '<td valign="top">Contrast could have done with a boost which would have helped a lot. Good angle and subject. 5</td>', 'Contrast could have done with a boost which would have helped a lot. Good angle and subject. 5', '2003-11-17 16:26:50.000000', NULL, 1),
(488251, 47047, 3569, '<td valign="top">Beautiful as Bryce should be.  Nice shot.  Wish I were there.</td>', 'Beautiful as Bryce should be.  Nice shot.  Wish I were there.', '2003-11-17 16:26:57.000000', NULL, 1),
(488254, 47018, 3569, '<td valign="top">Great dof, snow on sandstone, and back lightingof the greens.  Colors right on.  great shot in all ways.</td>', 'Great dof, snow on sandstone, and back lightingof the greens.  Colors right on.  great shot in all ways.', '2003-11-17 16:28:39.000000', NULL, 1),
(488255, 47283, 6667, '<td valign="top">Obviously we never get tired of playing with alphabet soup.  I am not sure of what I want to comment on, that is, I don''t know if I want the spoon in clear focus with the bowl out of focus; or a cleaner,  all  in focus shot.  I guesst the bottoom line is that the lack of sharpness detracts form this neat picture. The heavy shadow in the bottom of the bowl was adistraction.  In my humble opinion.</td>', 'Obviously we never get tired of playing with alphabet soup.  I am not sure of what I want to comment on, that is, I don''t know if I want the spoon in clear focus with the bowl out of focus; or a cleaner,  all  in focus shot.  I guesst the bottoom line is that the lack of sharpness detracts form this neat picture. The heavy shadow in the bottom of the bowl was adistraction.  In my humble opinion.', '2003-11-17 16:31:13.000000', NULL, 1),
(488257, 46832, 3569, '<td valign="top">The only problem I see or really can''t see is any texture.  The flash too the shadows out so evetything appears flattened.  Adding some contrast may help.  The idea is nice though.</td>', 'The only problem I see or really can''t see is any texture.  The flash too the shadows out so evetything appears flattened.  Adding some contrast may help.  The idea is nice though.', '2003-11-17 16:32:03.000000', NULL, 1),
(488259, 47361, 3569, '<td valign="top">Definitely not anemic.  Nice interpretation and shot.</td>', 'Definitely not anemic.  Nice interpretation and shot.', '2003-11-17 16:33:39.000000', NULL, 1),
(488260, 47366, 3569, '<td valign="top">Watch out they may tax it.  Nice interpretation.</td>', 'Watch out they may tax it.  Nice interpretation.', '2003-11-17 16:34:48.000000', NULL, 1),
(488262, 47263, 4482, '<td valign="top">The composition in this shot is great and so is the lighting.... too bad you over did it on the MeatImage. :-(  Still an 8 from me</td>', 'The composition in this shot is great and so is the lighting.... too bad you over did it on the MeatImage. :-(  Still an 8 from me', '2003-11-17 16:37:19.000000', NULL, 1),
(488272, 46672, 6668, '<td valign="top">very cute idea, I can tell alot of thought was put into this shot.  Nice work.</td>', 'very cute idea, I can tell alot of thought was put into this shot.  Nice work.', '2003-11-17 16:43:54.000000', NULL, 1),
(488276, 47336, 6668, '<td valign="top">very nice.</td>', 'very nice.', '2003-11-17 16:45:00.000000', NULL, 1),
(488277, 46454, 4210, '<td valign="top">Did you deliberately set this up so that the words were difficult to read? If so, I think it was probably a good choice. It makes the veiwer look longer in order to make some sense of it.</td>', 'Did you deliberately set this up so that the words were difficult to read? If so, I think it was probably a good choice. It makes the veiwer look longer in order to make some sense of it.', '2003-11-17 16:45:39.000000', NULL, 1),
(488278, 47250, 4210, '<td valign="top">Fits the challenge, but the center weighted composition is a bit boring.</td>', 'Fits the challenge, but the center weighted composition is a bit boring.', '2003-11-17 16:46:50.000000', NULL, 1),
(488282, 47270, 14272, '<td valign="top">Nice use of frame, clever enough to make viewer think a couple secs and then... AHA!... good blood (too good?), nice reflections... a simple and powerful picture</td>', 'Nice use of frame, clever enough to make viewer think a couple secs and then... AHA!... good blood (too good?), nice reflections... a simple and powerful picture', '2003-11-17 16:58:34.000000', NULL, 1),
(488285, 47300, 6667, '<td valign="top">I think I would have prefered a red mainstreet (or the entertainment district) featured shot as apposed the skyline.  Just my opinion though.</td>', 'I think I would have prefered a red mainstreet (or the entertainment district) featured shot as apposed the skyline.  Just my opinion though.', '2003-11-17 17:04:51.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(488286, 47049, 6667, '<td valign="top">In my humble opinion: the major building itself would have been more dramatic. . . especially with that sky.  To me, it is a case where less is more.</td>', 'In my humble opinion: the major building itself would have been more dramatic. . . especially with that sky.  To me, it is a case where less is more.', '2003-11-17 17:07:07.000000', NULL, 1),
(488287, 47145, 6667, '<td valign="top">Or looking down the barrel of a 45? In this case, I believe,  all of the shotshould have been in focus.</td>', 'Or looking down the barrel of a 45? In this case, I believe,  all of the shotshould have been in focus.', '2003-11-17 17:08:34.000000', NULL, 1),
(488288, 46804, 7889, '<td valign="top">Good dof and colour, shadows are a bit distracting for me, 5</td>', 'Good dof and colour, shadows are a bit distracting for me, 5', '2003-11-17 17:09:43.000000', NULL, 1),
(488290, 46362, 6667, '<td valign="top">Nice shot.  I think I would have prefered a different back drop though. . . and it takes two to bite! Just my opinion.</td>', 'Nice shot.  I think I would have prefered a different back drop though. . . and it takes two to bite! Just my opinion.', '2003-11-17 17:11:21.000000', NULL, 1),
(488293, 47195, 7889, '<td valign="top">Had trouble spotting her! good idea but the main subject is a bit on the small side. 5</td>', 'Had trouble spotting her! good idea but the main subject is a bit on the small side. 5', '2003-11-17 17:13:42.000000', NULL, 1),
(488295, 46516, 6667, '<td valign="top">Thorns?!  Literal?</td>', 'Thorns?!  Literal?', '2003-11-17 17:14:30.000000', NULL, 1),
(488298, 46653, 7889, '<td valign="top">This is my fav of the challenge. b&amp;w works well, good focus - 8</td>', 'This is my fav of the challenge. b&w works well, good focus - 8', '2003-11-17 17:17:56.000000', NULL, 1),
(488302, 47301, 6667, '<td valign="top">I have always felt that was a very powerful phrase.  You made it more so.  Like the gray tones.  Not so sure the building was needed though.  Would have cropped it out to convey more of the desolation or loneliness of the loss.  Just my humble opinion though.</td>', 'I have always felt that was a very powerful phrase.  You made it more so.  Like the gray tones.  Not so sure the building was needed though.  Would have cropped it out to convey more of the desolation or loneliness of the loss.  Just my humble opinion though.', '2003-11-17 17:21:08.000000', NULL, 1),
(488304, 47261, 6667, '<td valign="top">I realize the idea is "behind," however, the blurriness of the eight ball is distracting. I wouldd have prefered a clearer focus on both subjects.</td>', 'I realize the idea is "behind," however, the blurriness of the eight ball is distracting. I wouldd have prefered a clearer focus on both subjects.', '2003-11-17 17:23:37.000000', NULL, 1),
(488306, 47339, 6667, '<td valign="top">Damn!  Wished my camera had double exposeure capability.  Neat Idea.   Only the right hand walking in  on the figure wlaking out might suggest  a "pat on the but."!</td>', 'Damn!  Wished my camera had double exposeure capability.  Neat Idea.   Only the right hand walking in  on the figure wlaking out might suggest  a "pat on the but."!', '2003-11-17 17:27:16.000000', NULL, 1),
(488308, 47287, 6667, '<td valign="top">Great shot.  I thought Lugers were German made though!?  To me, the light scrathches on the barrel were somewhat distacting from the dramatic impact.</td>', 'Great shot.  I thought Lugers were German made though!?  To me, the light scrathches on the barrel were somewhat distacting from the dramatic impact.', '2003-11-17 17:29:50.000000', NULL, 1),
(488309, 46817, 6667, '<td valign="top">The blurriness of the shot distracts from the impact.</td>', 'The blurriness of the shot distracts from the impact.', '2003-11-17 17:31:17.000000', NULL, 1),
(488312, 47270, 6667, '<td valign="top">Damn!!!  that sends shivers down my spine just looking at that.  But then. . . that was your point, wasn''t it?  Nice work. Clean (the shot, that is,) and dramatic.</td>', 'Damn!!!  that sends shivers down my spine just looking at that.  But then. . . that was your point, wasn''t it?  Nice work. Clean (the shot, that is,) and dramatic.', '2003-11-17 17:36:30.000000', NULL, 1),
(488315, 47304, 6667, '<td valign="top">hey!! That''s mine!   I would have prefered more contrast.</td>', 'hey!! That''s mine!   I would have prefered more contrast.', '2003-11-17 17:38:55.000000', NULL, 1),
(488317, 46975, 6405, '<td valign="top">Very cool,10 !</td>', 'Very cool,10 !', '2003-11-17 17:40:04.000000', NULL, 1),
(488318, 47049, 6405, '<td valign="top">Nice points,10 !</td>', 'Nice points,10 !', '2003-11-17 17:40:29.000000', NULL, 1),
(488319, 46682, 11155, '<td valign="top">Interesting shapes and reflections</td>', 'Interesting shapes and reflections', '2003-11-17 17:40:29.000000', NULL, 1),
(488320, 47243, 6667, '<td valign="top">Feather up for emphasis, clean shot, crisp focus and simply dramatic.  it''s a winner (or should be).</td>', 'Feather up for emphasis, clean shot, crisp focus and simply dramatic.  it''s a winner (or should be).', '2003-11-17 17:41:00.000000', NULL, 1),
(488321, 46672, 11155, '<td valign="top">Cute.  Creative.</td>', 'Cute.  Creative.', '2003-11-17 17:41:05.000000', NULL, 1),
(488324, 46877, 8252, '<td valign="top">Awesome.  What happened to your camer?</td>', 'Awesome.  What happened to your camer?', '2003-11-17 17:44:58.000000', NULL, 1),
(488337, 47263, 6667, '<td valign="top">grapevine needed to be int he right ear.</td>', 'grapevine needed to be int he right ear.', '2003-11-17 18:20:45.000000', NULL, 1),
(488338, 46599, 6667, '<td valign="top">Focus needs to be on the two peas only with nothing in bac. . .  since that is the interpretation.</td>', 'Focus needs to be on the two peas only with nothing in bac. . .  since that is the interpretation.', '2003-11-17 18:24:50.000000', NULL, 1),
(488340, 46723, 6667, '<td valign="top">. . .but there is only one!</td>', '. . .but there is only one!', '2003-11-17 18:34:36.000000', NULL, 1),
(488344, 47195, 6667, '<td valign="top">No babe is evident!</td>', 'No babe is evident!', '2003-11-17 18:50:23.000000', NULL, 1),
(488347, 46853, 6667, '<td valign="top">Needs to be an eye level shot.</td>', 'Needs to be an eye level shot.', '2003-11-17 18:53:48.000000', NULL, 1),
(488349, 46890, 6667, '<td valign="top">Waite a minute!  In what part of the world are the bees still working?  Sharper focus would have helped bring attention to the bee.</td>', 'Waite a minute!  In what part of the world are the bees still working?  Sharper focus would have helped bring attention to the bee.', '2003-11-17 18:54:48.000000', NULL, 1),
(488350, 46837, 6667, '<td valign="top">All right, I give.  How did you get the duck to do that on cue????!  I wish he had done it with his back tail feathers though.</td>', 'All right, I give.  How did you get the duck to do that on cue????!  I wish he had done it with his back tail feathers though.', '2003-11-17 18:55:16.000000', NULL, 1),
(488352, 47283, 11709, '<td valign="top">amazed by your thought to put those letters together so that it matches the title so wonderful!</td>', 'amazed by your thought to put those letters together so that it matches the title so wonderful!', '2003-11-17 18:58:03.000000', NULL, 1),
(488354, 47313, 12253, '<td valign="top">That''s an interesting tatoo.  It looks typed, so I am curious how you actually got it on you (my guess it has to be some sort of print-transfer).  Good composition here, and good capture.  And a good literalistic interpretation of the phrase.</td>', 'That''s an interesting tatoo.  It looks typed, so I am curious how you actually got it on you (my guess it has to be some sort of print-transfer).  Good composition here, and good capture.  And a good literalistic interpretation of the phrase.', '2003-11-17 18:59:17.000000', NULL, 1),
(488358, 46975, 12253, '<td valign="top">An excellent capture of this squirrel.  Photographically, it''s right on.  But is it a literalistic interpretation of the phrase: You are Nuts?  This is "Your nuts", if you are the squirrel.  Works if its a sound alike literalism.</td>', 'An excellent capture of this squirrel.  Photographically, it''s right on.  But is it a literalistic interpretation of the phrase: You are Nuts?  This is "Your nuts", if you are the squirrel.  Works if its a sound alike literalism.', '2003-11-17 19:05:14.000000', NULL, 1),
(488359, 47358, 12253, '<td valign="top">Good literalism, and reminds me of Rowan and Martin''s laugh in!</td>', 'Good literalism, and reminds me of Rowan and Martin''s laugh in!', '2003-11-17 19:05:47.000000', NULL, 1),
(488360, 46682, 6667, '<td valign="top">In my humble opinion, this would have had more impact if ou cropped it a little shallower.  That is, more under the bridge. as the phrase implies.</td>', 'In my humble opinion, this would have had more impact if ou cropped it a little shallower.  That is, more under the bridge. as the phrase implies.', '2003-11-17 19:07:10.000000', NULL, 1),
(488361, 47303, 12253, '<td valign="top">An interesting shot, but I am not sure this is a literalism, as much as it is an anthropomorphic interpretation of a phrase.</td>', 'An interesting shot, but I am not sure this is a literalism, as much as it is an anthropomorphic interpretation of a phrase.', '2003-11-17 19:07:38.000000', NULL, 1),
(488366, 47164, 12253, '<td valign="top">Interesting sunset, but doesn''t really strike me as a literalistic interpretation.  Maybe pointing south.</td>', 'Interesting sunset, but doesn''t really strike me as a literalistic interpretation.  Maybe pointing south.', '2003-11-17 19:12:24.000000', NULL, 1),
(488368, 47323, 12253, '<td valign="top">good idea.  I think it could hae a little more kick to it if it were sharper and maybe leveled a little differently.</td>', 'good idea.  I think it could hae a little more kick to it if it were sharper and maybe leveled a little differently.', '2003-11-17 19:13:20.000000', NULL, 1),
(488370, 47326, 6667, '<td valign="top">This one could go under propaganda as well!</td>', 'This one could go under propaganda as well!', '2003-11-17 19:13:30.000000', NULL, 1),
(488376, 46914, 6667, '<td valign="top">What an impact.  I wish this would have had more contrast to it.  Great capture.</td>', 'What an impact.  I wish this would have had more contrast to it.  Great capture.', '2003-11-17 19:18:06.000000', NULL, 1),
(488382, 47122, 7628, '<td valign="top">I like the contrast of the wood against the blackness. I like the black band that blands into the blckness on the right, but whatever it is on the left/bottom distracts from the simplicity of the composition.  Could be sharper, larger DOF, and it feels a bit tilted to the left.</td>', 'I like the contrast of the wood against the blackness. I like the black band that blands into the blckness on the right, but whatever it is on the left/bottom distracts from the simplicity of the composition.  Could be sharper, larger DOF, and it feels a bit tilted to the left.', '2003-11-17 19:31:02.000000', NULL, 1),
(488384, 46832, 7628, '<td valign="top">There is some nice detail here, but yo could have gotten more with better lighting.  Light from the sides would create some nice depth, and not wash out the colors so much</td>', 'There is some nice detail here, but yo could have gotten more with better lighting.  Light from the sides would create some nice depth, and not wash out the colors so much', '2003-11-17 19:32:29.000000', NULL, 1),
(488387, 46976, 7628, '<td valign="top">I like the touch that the penny is from 1944 - saved for a long time!  Nice detail - the scratches on Abe and the lines in the hand.  Very sharp.  a bit bright in the bottom left corner</td>', 'I like the touch that the penny is from 1944 - saved for a long time!  Nice detail - the scratches on Abe and the lines in the hand.  Very sharp.  a bit bright in the bottom left corner', '2003-11-17 19:33:46.000000', NULL, 1),
(488390, 47338, 7628, '<td valign="top">what an unusual pipe.  Wish we could see further down.  Larger DOF would bring it all into focus. There are some nice textures in this subject - a bit more lighting from the side and behind would bring that out more - then it might make a good b&amp;w - try it out</td>', 'what an unusual pipe.  Wish we could see further down.  Larger DOF would bring it all into focus. There are some nice textures in this subject - a bit more lighting from the side and behind would bring that out more - then it might make a good b&w - try it out', '2003-11-17 19:36:01.000000', NULL, 1),
(488394, 46890, 7628, '<td valign="top">Having other flowers in the background help us to see how busy your bee is - nectar here nectar there!  Nice colors, I like the shallow DOF - the bees seems focused on this flower right now before it moves on.</td>', 'Having other flowers in the background help us to see how busy your bee is - nectar here nectar there!  Nice colors, I like the shallow DOF - the bees seems focused on this flower right now before it moves on.', '2003-11-17 19:38:06.000000', NULL, 1),
(488395, 47296, 7628, '<td valign="top">The shallow DOF helps us to focus on the subject, but the background is still a bit busy.  It would help if the light were brighter on the prairie dog (?)  rather thanon the trunk.</td>', 'The shallow DOF helps us to focus on the subject, but the background is still a bit busy.  It would help if the light were brighter on the prairie dog (?)  rather thanon the trunk.', '2003-11-17 19:39:47.000000', NULL, 1),
(488396, 47236, 7628, '<td valign="top">And surround vision too!  Nice visual representation of being surrounded by sound.  Wish there was more light on the central subject so it would stand out more from the black.</td>', 'And surround vision too!  Nice visual representation of being surrounded by sound.  Wish there was more light on the central subject so it would stand out more from the black.', '2003-11-17 19:41:01.000000', NULL, 1),
(488397, 46362, 7628, '<td valign="top">funny.  The pink and yellow(relatively yellow! but basically white) of the dentures stands out well from the clear glass and water.</td>', 'funny.  The pink and yellow(relatively yellow! but basically white) of the dentures stands out well from the clear glass and water.', '2003-11-17 19:44:20.000000', NULL, 1),
(488404, 47315, 12253, '<td valign="top">Good tones.  Sorry, I don''t get this literalism.</td>', 'Good tones.  Sorry, I don''t get this literalism.', '2003-11-17 20:03:28.000000', NULL, 1),
(488405, 47287, 12253, '<td valign="top">I guess this works, figuratively, but actually, the smoking gun expression means exactly that.  I think it would have been funny to see the gun with a cigarette in its barrell, smoking.</td>', 'I guess this works, figuratively, but actually, the smoking gun expression means exactly that.  I think it would have been funny to see the gun with a cigarette in its barrell, smoking.', '2003-11-17 20:05:11.000000', NULL, 1),
(488407, 47027, 12253, '<td valign="top">Seems you and several others had the same idea.  Good exposure on the shot.  As I told the other person, I think it would have been interesting to see a nonverbal way to indicate counting.  A hand pointing, a tally sheet, a calculator...</td>', 'Seems you and several others had the same idea.  Good exposure on the shot.  As I told the other person, I think it would have been interesting to see a nonverbal way to indicate counting.  A hand pointing, a tally sheet, a calculator...', '2003-11-17 20:07:02.000000', NULL, 1),
(488412, 47304, 7628, '<td valign="top">Just enough of the road and grass at the side of the road to frame the fork perfectly. Funny, simple.</td>', 'Just enough of the road and grass at the side of the road to frame the fork perfectly. Funny, simple.', '2003-11-17 20:17:12.000000', NULL, 1),
(488416, 46672, 7628, '<td valign="top">I like that you even carved cushions into your couch!  I like the curve behind the potato mmicking its shape.  But I think It would have stood out better if the potato were spot-lit, the background is distracting with the pink and flowers.</td>', 'I like that you even carved cushions into your couch!  I like the curve behind the potato mmicking its shape.  But I think It would have stood out better if the potato were spot-lit, the background is distracting with the pink and flowers.', '2003-11-17 20:20:51.000000', NULL, 1),
(488419, 46789, 7628, '<td valign="top">So sad!  Nice choice of oreos - the white and dark brown contrast well.  Wish the backgrouns were black, black black, and crumbs and all sharper.</td>', 'So sad!  Nice choice of oreos - the white and dark brown contrast well.  Wish the backgrouns were black, black black, and crumbs and all sharper.', '2003-11-17 20:22:28.000000', NULL, 1),
(488422, 46837, 7628, '<td valign="top">I didn''t see it from the thumbnail - but I love the droplets of water flying off as the duck shakes.    The blurr of green makes wonderful motion, and the tail is sharp.  Wish the water weren''t so yellow.  Could you desaturate the yellows?  The beak is suck a deep yellow you might get most out of the water without loosing the beak.  Or after the competition, spot edit.</td>', 'I didn''t see it from the thumbnail - but I love the droplets of water flying off as the duck shakes.    The blurr of green makes wonderful motion, and the tail is sharp.  Wish the water weren''t so yellow.  Could you desaturate the yellows?  The beak is suck a deep yellow you might get most out of the water without loosing the beak.  Or after the competition, spot edit.', '2003-11-17 20:25:21.000000', NULL, 1),
(488423, 47236, 12253, '<td valign="top">Not sure what I''m looking at, and it thus makes it hard to judge how this is a literalism.  However, it is a very nice photo., though it might be good to try to get some shadow detail on the stairwell (I assume that''s what it is).  If I were to literally interpet surround sound, I might think of people surrounding a speaker, or a person playing an instrument.</td>', 'Not sure what I''m looking at, and it thus makes it hard to judge how this is a literalism.  However, it is a very nice photo., though it might be good to try to get some shadow detail on the stairwell (I assume that''s what it is).  If I were to literally interpet surround sound, I might think of people surrounding a speaker, or a person playing an instrument.', '2003-11-17 20:25:55.000000', NULL, 1),
(488425, 47257, 7628, '<td valign="top">Very nice!  nice colors, well lit.  I might crop in from the sides a bit more - make that single thread seem even more thin. 9</td>', 'Very nice!  nice colors, well lit.  I might crop in from the sides a bit more - make that single thread seem even more thin. 9', '2003-11-17 20:27:11.000000', NULL, 1),
(488426, 46834, 12253, '<td valign="top">Nice scenic.   A tough crop because you can''t easily avoid the almost center split here without losing the tree or adding too much sky.  A good literalism for this phrase to me might have been a no splashing sign at a pool (perhaps off season, depending on where you live), a closed theme park wave pool, a bottle of hair straightener, ...</td>', 'Nice scenic.   A tough crop because you can''t easily avoid the almost center split here without losing the tree or adding too much sky.  A good literalism for this phrase to me might have been a no splashing sign at a pool (perhaps off season, depending on where you live), a closed theme park wave pool, a bottle of hair straightener, ...', '2003-11-17 20:29:34.000000', NULL, 1),
(488428, 46516, 7628, '<td valign="top">Interesting contrast between the shiny silver and the matte rose.  I''d crop in from the left - the out of focus stuff doesnt; add anything to the picture and is distracting.  Watch the refelctions in the silver - next time hold up a solid color paper close enough to fill the "mirror" of the object.</td>', 'Interesting contrast between the shiny silver and the matte rose.  I''d crop in from the left - the out of focus stuff doesnt; add anything to the picture and is distracting.  Watch the refelctions in the silver - next time hold up a solid color paper close enough to fill the "mirror" of the object.', '2003-11-17 20:30:02.000000', NULL, 1),
(488431, 47164, 7628, '<td valign="top">nice silouette, great sky.  too bad the "s" is backwards (could you flip the image?)  Could it be a bit sharper?</td>', 'nice silouette, great sky.  too bad the "s" is backwards (could you flip the image?)  Could it be a bit sharper?', '2003-11-17 20:31:51.000000', NULL, 1),
(488432, 46672, 12253, '<td valign="top">VERY funny.  Very clever.  Photographically, I would like to have seen some more contrast or lighting on the couch itself, and a noncentered composition (Personally, I think the potatoe speaks for itself without being the center of the composition) but the idea is fantastic.  Now why didn''t I think of that ;)</td>', 'VERY funny.  Very clever.  Photographically, I would like to have seen some more contrast or lighting on the couch itself, and a noncentered composition (Personally, I think the potatoe speaks for itself without being the center of the composition) but the idea is fantastic.  Now why didn''t I think of that ;)', '2003-11-17 20:32:03.000000', NULL, 1),
(488433, 47055, 7628, '<td valign="top">such a nice pink sky - "love"?  I like the silouette of the deciduous tree - it is a bit busy on the right hand side.  I''d crop the bottom to bring the attention more onto the silouettes and the sky.</td>', 'such a nice pink sky - "love"?  I like the silouette of the deciduous tree - it is a bit busy on the right hand side.  I''d crop the bottom to bring the attention more onto the silouettes and the sky.', '2003-11-17 20:33:43.000000', NULL, 1),
(488434, 47221, 12253, '<td valign="top">You have your bases covered with two literalisms.  Ooh,  I just made one... LOL.  The hard part of this challenge, in my opinion, was to illustrate the challenge and also to come up with a compelling photo.  I think the composition and lighting here could have been more interesting, but this comparese favorably to others who did the same thing.</td>', 'You have your bases covered with two literalisms.  Ooh,  I just made one... LOL.  The hard part of this challenge, in my opinion, was to illustrate the challenge and also to come up with a compelling photo.  I think the composition and lighting here could have been more interesting, but this comparese favorably to others who did the same thing.', '2003-11-17 20:34:29.000000', NULL, 1),
(488435, 47340, 7628, '<td valign="top">Now you don''t know where that money has been!  Nice idea.  A bit larger DOF and get the chin in focus.  Add some light from the top or side to differentiate the face from the neck and add a bit more dimension to the picture.  Maybe we could see some white teeth?</td>', 'Now you don''t know where that money has been!  Nice idea.  A bit larger DOF and get the chin in focus.  Add some light from the top or side to differentiate the face from the neck and add a bit more dimension to the picture.  Maybe we could see some white teeth?', '2003-11-17 20:36:03.000000', NULL, 1),
(488439, 47326, 7628, '<td valign="top">hee hee!  Very modern literalism.  Nice composition with the disc in the upper left.  Wish the hand were a bit sharper and included the thumb</td>', 'hee hee!  Very modern literalism.  Nice composition with the disc in the upper left.  Wish the hand were a bit sharper and included the thumb', '2003-11-17 20:37:28.000000', NULL, 1),
(488440, 46653, 12253, '<td valign="top">This is a good photo, and a good literalism.  I  think the spile could be a little more "instantly" recognizable if you included more of the context.  I think the contrast and tones of the photo are compelling, but the centric design is less-so.</td>', 'This is a good photo, and a good literalism.  I  think the spile could be a little more "instantly" recognizable if you included more of the context.  I think the contrast and tones of the photo are compelling, but the centric design is less-so.', '2003-11-17 20:37:38.000000', NULL, 1),
(488441, 47172, 7628, '<td valign="top">Wish that fence weren''t there at the bottom.  I like the composition otherwise - the man, the horsee, the trees - has nice balance (even if it does not have drama).</td>', 'Wish that fence weren''t there at the bottom.  I like the composition otherwise - the man, the horsee, the trees - has nice balance (even if it does not have drama).', '2003-11-17 20:39:24.000000', NULL, 1),
(488442, 47257, 12253, '<td valign="top">A nice capture of the rope, and the choice of colored rope was good.  This one is a good illustration of one of the two camps here.  I guess this is a literalism because indeed it''s hanging by a thread.  But it''s not, as the other camp has it, a "so litteral its incorrect or absurd interpration".  Perhaps it''s just that some phrases are based in literalism, and others are just "misinterpreted" that way (which makes them funnier).</td>', 'A nice capture of the rope, and the choice of colored rope was good.  This one is a good illustration of one of the two camps here.  I guess this is a literalism because indeed it''s hanging by a thread.  But it''s not, as the other camp has it, a "so litteral its incorrect or absurd interpration".  Perhaps it''s just that some phrases are based in literalism, and others are just "misinterpreted" that way (which makes them funnier).', '2003-11-17 20:39:46.000000', NULL, 1),
(488443, 47004, 12253, '<td valign="top">Pretty shot, and a good literalistic interpretation.  My subjective suggestion would be to crop a little on the right, so the focal point, the light house and that wonderful big wave, were not so centric here.</td>', 'Pretty shot, and a good literalistic interpretation.  My subjective suggestion would be to crop a little on the right, so the focal point, the light house and that wonderful big wave, were not so centric here.', '2003-11-17 20:41:44.000000', NULL, 1),
(488444, 47243, 7628, '<td valign="top">Nice birds!  I like the crouching position balanced by the striding confidence of the other bird.  Just enough suggestion of a ground for them to stand on, and nothing but white behind really focuses our attention of the birds, their expressions and personality.  Nice range of grays, nice detail.  Later, edit out those whispy lines on the right. 10</td>', 'Nice birds!  I like the crouching position balanced by the striding confidence of the other bird.  Just enough suggestion of a ground for them to stand on, and nothing but white behind really focuses our attention of the birds, their expressions and personality.  Nice range of grays, nice detail.  Later, edit out those whispy lines on the right. 10', '2003-11-17 20:41:55.000000', NULL, 1),
(488445, 47352, 12253, '<td valign="top">Interesting capture and tones.</td>', 'Interesting capture and tones.', '2003-11-17 20:42:07.000000', NULL, 1),
(488447, 46817, 12253, '<td valign="top">Good literalistic capture.  Photo is good, but I think I would have preferred it with more DOF.</td>', 'Good literalistic capture.  Photo is good, but I think I would have preferred it with more DOF.', '2003-11-17 20:43:06.000000', NULL, 1),
(488448, 47353, 7628, '<td valign="top">The shadow and blue color really adds drama, and the frame of the rope around your subject has real meaning - however grim.  Crop the top to get rid of the line of the ceiling. 8</td>', 'The shadow and blue color really adds drama, and the frame of the rope around your subject has real meaning - however grim.  Crop the top to get rid of the line of the ceiling. 8', '2003-11-17 20:43:26.000000', NULL, 1),
(488453, 47361, 12253, '<td valign="top">Good literalism.  I think the hot spot in the background really detracts here, as well as a couple other smaller factors.  I don''t think the centered composition is very dramatic here, as is the subject.  Also, I wonder what the object is above, there''s a little there, so it attracts my attention, but not enough to really see what it is.  I think this might have worked well just as a close up of the separated liquids, focusing on the lighting and colors to give it some snap!</td>', 'Good literalism.  I think the hot spot in the background really detracts here, as well as a couple other smaller factors.  I don''t think the centered composition is very dramatic here, as is the subject.  Also, I wonder what the object is above, there''s a little there, so it attracts my attention, but not enough to really see what it is.  I think this might have worked well just as a close up of the separated liquids, focusing on the lighting and colors to give it some snap!', '2003-11-17 20:45:30.000000', NULL, 1),
(488454, 47263, 7628, '<td valign="top">fairie lighting - soft and shimmering,  I like how the curce of hair mimics the curve of the vine, and her eyes make it look like she is listenning. Wish the "vine" came out more into the white space. 8</td>', 'fairie lighting - soft and shimmering,  I like how the curce of hair mimics the curve of the vine, and her eyes make it look like she is listenning. Wish the "vine" came out more into the white space. 8', '2003-11-17 20:45:38.000000', NULL, 1),
