(488732, 47197, 8125, '<td valign="top">Love this idea!  I would like to see the same set up with the label on the can removed.  Good lighting and composition.</td>', 'Love this idea!  I would like to see the same set up with the label on the can removed.  Good lighting and composition.', '2003-11-18 08:21:13.000000', NULL, 1),
(488733, 47287, 8125, '<td valign="top">Awesome!  So far one of my favorite shots in the challenge.  Love the lighting, composition, subject.  The smoke looks great...  Well Done!!!</td>', 'Awesome!  So far one of my favorite shots in the challenge.  Love the lighting, composition, subject.  The smoke looks great...  Well Done!!!', '2003-11-18 08:24:07.000000', NULL, 1),
