(491434, 47357, 5112, '<td valign="top">This is beautiful!  Every time I look at it, I have to laugh!  Very creative!  ~10</td>', 'This is beautiful!  Every time I look at it, I have to laugh!  Very creative!  ~10', '2003-11-20 21:55:41.000000', NULL, 1),
