(491602, 47349, 10260, '<td valign="top">Wonderful photo.  I can almost feel the motion in his dance.  Colors are bright and detail good.  You''ve captured his motion, making it alive for me.  Great photo. 10</td>', 'Wonderful photo.  I can almost feel the motion in his dance.  Colors are bright and detail good.  You''ve captured his motion, making it alive for me.  Great photo. 10', '2003-11-21 02:19:27.000000', NULL, 1),
(491603, 46672, 10260, '<td valign="top">This is sooooo clever!  I love it.  I think it could have been lightened some,  but still is great. That must have taken some time.....making a couch potato. :)  8</td>', 'This is sooooo clever!  I love it.  I think it could have been lightened some,  but still is great. That must have taken some time.....making a couch potato. :)  8', '2003-11-21 02:21:46.000000', NULL, 1),
(491604, 47347, 10260, '<td valign="top">Beautiful photo.  The three.....make that four colors only give it a nice clean look. Great composition too.  9</td>', 'Beautiful photo.  The three.....make that four colors only give it a nice clean look. Great composition too.  9', '2003-11-21 02:23:59.000000', NULL, 1),
(491605, 47243, 10260, '<td valign="top">This is so nice.   almost looks like a breeze there with the ruffled feathers and feel of motion in the background.  They could be dancing. :)</td>', 'This is so nice.   almost looks like a breeze there with the ruffled feathers and feel of motion in the background.  They could be dancing. :)', '2003-11-21 02:27:31.000000', NULL, 1),
(491681, 47366, 11800, '<td valign="top">This is funny in an unexpected way. It is over and beyond what would be expected for the saying. Good job.</td>', 'This is funny in an unexpected way. It is over and beyond what would be expected for the saying. Good job.', '2003-11-21 08:52:55.000000', NULL, 1),
(491683, 47063, 11800, '<td valign="top">Nice and clean, if that can be said for live worms! A good idea, expertly executed.</td>', 'Nice and clean, if that can be said for live worms! A good idea, expertly executed.', '2003-11-21 08:54:22.000000', NULL, 1),
(491686, 47347, 11800, '<td valign="top">The lighting, composition and exposure are excellent. However, I believe the saying is "don''t put all your...". I didn''t lower your score because of that!</td>', 'The lighting, composition and exposure are excellent. However, I believe the saying is "don''t put all your...". I didn''t lower your score because of that!', '2003-11-21 09:00:19.000000', NULL, 1),
(491689, 47302, 11800, '<td valign="top">This is beautiful. So simple, it makes me want to cry.</td>', 'This is beautiful. So simple, it makes me want to cry.', '2003-11-21 09:01:30.000000', NULL, 1),
(491690, 46653, 11800, '<td valign="top">This is a great shot, but it''s showing the opposite of the saying. Maybe if I could see a glass rim in the shot it would have been scored higher. 7<br/>I like the color,lighting and clarity of the water drop.</td>', 'This is a great shot, but it''s showing the opposite of the saying. Maybe if I could see a glass rim in the shot it would have been scored higher. 7I like the color,lighting and clarity of the water drop.', '2003-11-21 09:07:25.000000', NULL, 1),
(491693, 46853, 11800, '<td valign="top">I like the idea. I think it would have been better if you had used a lower point of view so the wicks and flames were more obvious.</td>', 'I like the idea. I think it would have been better if you had used a lower point of view so the wicks and flames were more obvious.', '2003-11-21 09:11:33.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(491730, 46837, 9411, '<td valign="top">Technically off a ducks head, but I won''t quibble over a small thing like that! Very nice capture of motion, Getting the body in focus and having the drops be distinct is great.  8</td>', 'Technically off a ducks head, but I won''t quibble over a small thing like that! Very nice capture of motion, Getting the body in focus and having the drops be distinct is great.  8', '2003-11-21 10:19:32.000000', NULL, 1),
(491731, 47336, 9411, '<td valign="top">Very nice use of a square/centred format. Wonderful light/colour treatment. Detail, well WOW...  10</td>', 'Very nice use of a square/centred format. Wonderful light/colour treatment. Detail, well WOW...  10', '2003-11-21 10:20:34.000000', NULL, 1),
