(492988, 47333, 13576, '<td valign="top">I love tis photo. The colors really make it feel illuminated. It is a bit grainy though, and  I feel the focus could have been a bit sharper up front. -7-</td>', 'I love tis photo. The colors really make it feel illuminated. It is a bit grainy though, and  I feel the focus could have been a bit sharper up front. -7-', '2003-11-23 22:00:15.000000', NULL, 1),
(492989, 47194, 13576, '<td valign="top">Great for the challenge. Gave me a good chuckle. I think there is too much contrast here. The light is really light and the dark is really dark. Other than that, good job. - 8 -</td>', 'Great for the challenge. Gave me a good chuckle. I think there is too much contrast here. The light is really light and the dark is really dark. Other than that, good job. - 8 -', '2003-11-23 22:02:00.000000', NULL, 1),
(492990, 47326, 13576, '<td valign="top">Very clever. Skin feels a bit too red for my taste.  Other than that, I really like this. -8-</td>', 'Very clever. Skin feels a bit too red for my taste.  Other than that, I really like this. -8-', '2003-11-23 22:03:39.000000', NULL, 1),
